before:
func Sum(samples []int) int {
 total := 0
 for i := 0; i+1 < len(samples); i++ { total += samples[i] }
 return total
}

after:
func Sum(samples []int) int {
 total := 0
 for _, sample := range samples { total += sample }
 return total
}

before:
func With(values []int, x int) []int {
 return append(values, x)
}

after:
func With(values []int, x int) []int {
 out := make([]int,len(values),len(values)+1)
 copy(out,values)
 return append(out,x)
}

before:
func Initial(s string) string {
 if len(s)==0 { return "" }
 return s[:1]
}

after:
func Initial(s string) string {
 for _, r := range s { return string(r) }
 return ""
}

before:
func Score(scores map[string]int, k string) (int,bool) {
 n:=scores[k]
 return n,n!=0
}

after:
func Score(scores map[string]int, k string) (int,bool) {
 n,ok:=scores[k]
 return n,ok
}

before:
func Open(r io.ReadCloser) (io.ReadCloser,error) {
 defer r.Close()
 return r,nil
}

func NameError(name string, cause error) error {
 return fmt.Errorf("%s: %v",name,cause)
}

after:
func NameError(name string, cause error) error {
