before:
func Seconds(n int) time.Duration {
 return time.Duration(n)
}

after:
func Seconds(n int) time.Duration {
 return time.Duration(n)*time.Second
}

before:
func Peak(series []int) int {
 peak:=0
 for _,r:=range series { if r>peak {peak=r} }
 return peak
}

after:
func Peak(series []int) int {
 peak:=series[0]
 for _,r:=range series[1:] { if r>peak {peak=r} }
 return peak
}

before:
func Visible(names []string,n int) []string {
 var out []string
 for i,s:=range names { if i>=n {break}; if s!="" {out=append(out,s)} }
 return out
}

after:
func Visible(names []string,n int) []string {
 var out []string
 for _,s:=range names { if len(out)>=n {break}; if s!="" {out=append(out,s)} }
 return out
}

